package jtime

// The tables in this file were dumped straight out of a JDK 21 runtime (the one the reference
// command runs on) rather than written by hand: the names are whatever CLDR ships with that JDK.
// The month and weekday arrays are the strings SimpleDateFormat itself produces for MMM/MMMM/
// LLL/LLLL/EEE/EEEE, which are *not* always the DateFormatSymbols arrays (German MMM is "Jan"
// where DateFormatSymbols.getShortMonths() has "Jan."); the alt* arrays are the DateFormatSymbols
// ones, which parsing also accepts.

// localeData is the date part of a java.util.Locale: the names SimpleDateFormat prints and the
// week rules java.util.Calendar uses for that locale.
type localeData struct {
	monthsShort      [12]string
	monthsLong       [12]string
	monthsStandShort [12]string
	monthsStandLong  [12]string
	weekdaysShort    [7]string
	weekdaysLong     [7]string
	amPM             [2]string
	eras             [2]string
	altMonthsLong    [12]string
	altMonthsShort   [12]string
	altWeekdaysLong  [7]string
	altWeekdaysShort [7]string
	firstDayOfWeek   int
	minimalDays      int
}

